from collections import deque

def time_required_to_buy(tickets, k):
    n = len(tickets)
    remaining = tickets[:]
    queue = deque(range(n))                                                # everyone starts in line, in their original order
    time = 0
    while True:
        idx = queue.popleft()                                              # the person at the FRONT buys one ticket
        remaining[idx] -= 1
        time += 1
        if idx == k and remaining[idx] == 0:
            return time                                                   # person k just finished: this is the answer
        if remaining[idx] > 0:
            queue.append(idx)                                             # still needs more tickets: go to the BACK of the line


if __name__ == "__main__":
    print(time_required_to_buy([2, 3, 2], 2))

