import java.util.*;

public class Main {
    int timeRequiredToBuy(int[] tickets, int k) {
        int n = tickets.length;
        int[] remaining = tickets.clone();
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) queue.addLast(i);                              // everyone starts in line, in their original order
        int time = 0;
        while (true) {
            int idx = queue.pollFirst();                                              // the person at the FRONT buys one ticket
            remaining[idx]--;
            time++;
            if (idx == k && remaining[idx] == 0) return time;                             // person k just finished: this is the answer
            if (remaining[idx] > 0) queue.addLast(idx);                                   // still needs more tickets: go to the BACK of the line
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] tickets = {2, 3, 2};
        System.out.println(solution.timeRequiredToBuy(tickets, 2));
    }
}

