def time_required_to_buy(tickets, k):
    total = 0
    for i, t in enumerate(tickets):
        if i <= k:
            total += min(t, tickets[k])                                    # person i is served BEFORE k in every round up to k's LAST ticket
        else:
            total += min(t, tickets[k] - 1)                                # person i is served AFTER k, so their FINAL round doesn't count
    return total


if __name__ == "__main__":
    print(time_required_to_buy([5, 1, 1, 1], 0))

